#include <shared_mutex>
#include <thread>
#include <vector>
#include <iostream>
#include <chrono>

class ReadWriteData {
public:
    void read() const {
        std::shared_lock<std::shared_timed_mutex> lock(mutex_);
        std::cout << "Reading data: " << data_ << std::endl;
    }
    void write(int value) {
        std::unique_lock<std::shared_timed_mutex> lock(mutex_);
        data_ = value;
        std::cout << "Writing data: " << data_ << std::endl;
    }
    bool try_read_with_timeout(const std::chrono::milliseconds& timeout) const {
        std::shared_lock<std::shared_timed_mutex> lock(mutex_, std::defer_lock);
        if (lock.try_lock_for(timeout)) {
            std::cout << "Successfully acquired shared lock within timeout. Data: " << data_ << std::endl;
            return true;
        } else {
            std::cout << "Failed to acquire shared lock within timeout." << std::endl;
            return false;
        }
    }
private:
    mutable std::shared_timed_mutex mutex_;
    int data_ = 0;
};

int main() {
    ReadWriteData sharedData;
    sharedData.write(42);
    std::vector<std::thread> threads;
    for (int i = 0; i < 5; ++i) {
        threads.emplace_back([&sharedData, i]() {
            if (sharedData.try_read_with_timeout(std::chrono::milliseconds(100))) {
                // read succeeded
            } else {
                // read timed out
            }
        });
    }
    for (auto& t : threads) {
        t.join();
    }
    return 0;
}
